export class ProjectInvoices {
  private readonly service = inject(InvoiceService);

  readonly projectId = input.required<number>();
  /** The currency of the client the job is for; the money shown is in it. */
  readonly currency = input.required<CurrencyCode>();
  /** Emits when an invoice is sent or cancelled, changing how much has been invoiced on the project. */
  readonly invoiced = output<void>();

  protected readonly invoices = rxResource({
    params: () => this.projectId(),
    stream: ({ params }) => this.service.listForProject(params),
  });
  protected readonly list = computed(() => (this.invoices.hasValue() ? this.invoices.value() : []));
  // Earliest due first when sorting by due date (ties by invoice number); otherwise invoice-number order.
  protected readonly sortByDue = signal(false);
  protected readonly rows = computed(() =>
    this.sortByDue()
      ? [...this.list()].sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.id - b.id)
      : this.list(),
  );
  // Sum in whole cents so the total is exact rather than accumulating floating-point error. Void
  // invoices were cancelled, so they do not count.
  protected readonly totalCents = computed(() =>
    this.list()
      .filter((i) => i.status !== 'VOID')
      .reduce((sum, i) => sum + Math.round(i.amount * 100), 0),
  );

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  // The invoice whose send or cancel request is in flight.
  protected readonly busy = signal<number | null>(null);
  protected readonly sendError = signal<string | null>(null);
  protected readonly cancelError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group(
    {
      amount: ['', [Validators.min(0.01), Validators.pattern(/^\d+(\.\d{1,2})?$/)]],
      issuedDate: [''],
      dueDate: [''],
    },
    { validators: dueNotBeforeIssued },
  );

  protected showDueError(): boolean {
    return this.form.hasError('dueBeforeIssued') && this.form.controls.dueDate.dirty;
  }

  protected showError(): boolean {
    const control = this.form.controls.amount;
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const { amount, issuedDate, dueDate } = this.form.getRawValue();
    const invoice = {
      ...(amount !== '' && amount !== null ? { amount: Number(amount) } : {}),
      ...(issuedDate ? { issuedDate } : {}),
      ...(dueDate ? { dueDate } : {}),
    };
    this.service.create(this.projectId(), invoice).subscribe({
      next: (created) => {
        this.invoices.update((list) => [...(list ?? []), created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the invoice. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected send(invoiceId: number): void {
    this.busy.set(invoiceId);
    this.sendError.set(null);
    this.service.send(this.projectId(), invoiceId).subscribe({
      next: (sent) => {
        this.replace(sent);
        this.busy.set(null);
        this.invoiced.emit();
      },
      error: () => {
        this.sendError.set('Could not send the invoice. Please try again.');
        this.busy.set(null);
      },
    });
  }

  protected cancel(invoiceId: number): void {
    this.busy.set(invoiceId);
    this.cancelError.set(null);
    this.service.cancel(this.projectId(), invoiceId).subscribe({
      next: (voided) => {
        this.replace(voided);
        this.busy.set(null);
        this.invoiced.emit();
      },
      error: () => {
        this.cancelError.set('Could not cancel the invoice. Please try again.');
        this.busy.set(null);
      },
    });
  }

  private replace(updated: ProjectInvoice): void {
    this.invoices.update((list) => (list ?? []).map((i) => (i.id === updated.id ? updated : i)));
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export const INVOICE_STATUSES = ['DRAFT', 'SENT', 'PARTIAL', 'PAID', 'VOID'] as const;

export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

export interface Invoice {
  id: number;
  projectId: number;
  /** The currency of the client the invoice is for; its money is in it. */
  currency: CurrencyCode;
  amount: number;
  status: InvoiceStatus;
  /** ISO date (yyyy-MM-dd) the invoice was issued. */
  issuedDate: string;
  /** ISO date (yyyy-MM-dd) payment is due. */
  dueDate: string;
}

/** An invoice as listed for its project, with how much is still left to pay after any payments. */
export interface ProjectInvoice extends Invoice {
  amountDue: number;
}

/** An invoice as listed across all projects, with the name of the project it is for. */
export interface InvoiceSummary extends Invoice {
  projectName: string;
}

/** One page of the invoices listed across all projects; pages are numbered from zero. */
export interface InvoicePage {
  items: InvoiceSummary[];
  page: number;
  size: number;
  totalItems: number;
  totalPages: number;
}

/** An invoice as listed on a client's statement: its project's name and how much is left to pay. */
export interface StatementInvoice extends ProjectInvoice {
  projectName: string;
}

/** One job on a client's statement: its invoices and what is still owed on them. */
export interface StatementJob {
  projectId: number;
  projectName: string;
  invoices: StatementInvoice[];
  subtotal: number;
}

/** A client's invoices across all their projects, also grouped by job, with the total they still owe. */
export interface ClientStatement {
  clientId: number;
  clientName: string;
  /** The client's currency; every figure on the statement is in it. */
  currency: CurrencyCode;
  invoices: StatementInvoice[];
  jobs: StatementJob[];
  /** The total invoiced on the client's sent invoices (drafts and void ones are left out). */
  invoiced: number;
  /** How much of what was invoiced has been paid. */
  paid: number;
  /** The grand total still owed: what was invoiced less what was paid. */
  outstanding: number;
}

/** One thing an invoice charges for; its amount is quantity times unit price. */
export interface LineItem {
  id: number;
  description: string;
  qty: number;
  /** What the quantity counts, such as hours; null when the line does not say. */
  unit: string | null;
  unitPrice: number;
  amount: number;
}

/**
 * A single invoice with the line items it is built from: their subtotal, the percentage discount and
 * what it takes off, and the sales tax percentage and what it adds after the discount; its amount is
 * the subtotal less the discount plus the tax.
 */
export interface InvoiceDetail extends Invoice {
  subtotal: number;
  discountPct: number;
  discount: number;
  taxPct: number;
  tax: number;
  lineItems: LineItem[];
}

export interface NewLineItem {
  description: string;
  qty: number;
  unit: string | null;
  unitPrice: number;
}

export interface NewInvoice {
  /** Raises the invoice as one figure; omit to start an empty draft built up from line items. */
  amount?: number;
  /** Defaults to today on the server when omitted. */
  issuedDate?: string;
  /** Defaults to 30 days after the issue date on the server when omitted. */
  dueDate?: string;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  /** One page (numbered from zero) of the invoices across all projects, optionally narrowed to one status. */
  listAll(page: number, status?: InvoiceStatus): Observable<InvoicePage> {
    const params: Record<string, string | number> = status ? { status, page } : { page };
    return this.http.get<InvoicePage>('/api/invoices', { params });
  }

  listForProject(projectId: number): Observable<ProjectInvoice[]> {
    return this.http.get<ProjectInvoice[]>(`/api/projects/${projectId}/invoices`);
  }

  statementForClient(clientId: number): Observable<ClientStatement> {
    return this.http.get<ClientStatement>(`/api/clients/${clientId}/statement`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<ProjectInvoice> {
    return this.http.post<ProjectInvoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  get(projectId: number, invoiceId: number): Observable<InvoiceDetail> {
    return this.http.get<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}`);
  }

  addLineItem(projectId: number, invoiceId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items`, item);
  }

  updateLineItem(projectId: number, invoiceId: number, lineItemId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(
      `/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`,
      item,
    );
  }

  removeLineItem(projectId: number, invoiceId: number, lineItemId: number): Observable<InvoiceDetail> {
    return this.http.delete<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`);
  }

  /** Sets the percentage taken off a draft invoice; zero removes the discount. */
  applyDiscount(projectId: number, invoiceId: number, discountPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/discount`, { discountPct });
  }

  /** Sets the sales tax percentage added to a draft invoice after its discount; zero removes the tax. */
  applyTax(projectId: number, invoiceId: number, taxPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/tax`, { taxPct });
  }

  send(projectId: number, invoiceId: number): Observable<ProjectInvoice> {
    return this.http.post<ProjectInvoice>(`/api/projects/${projectId}/invoices/${invoiceId}/send`, null);
  }

  /** Cancels a sent invoice so it is no longer owed; it then reads VOID. */
  cancel(projectId: number, invoiceId: number): Observable<ProjectInvoice> {
    return this.http.post<ProjectInvoice>(`/api/projects/${projectId}/invoices/${invoiceId}/cancel`, null);
  }
}
-- An invoice can add a percentage sales tax on top of what is owed after any discount. The stored
-- amount remains what is owed, so it is now the discounted subtotal plus the tax; existing invoices
-- have no tax.
ALTER TABLE invoice ADD COLUMN tax_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_tax_pct_range CHECK (tax_pct >= 0 AND tax_pct <= 100);
-- Each client is billed in their own currency (ISO 4217 code); existing clients keep US dollars.
ALTER TABLE client ADD COLUMN currency VARCHAR(3) DEFAULT 'USD' NOT NULL;
ALTER TABLE client ADD CONSTRAINT client_currency_known CHECK (currency IN ('USD', 'EUR', 'GBP', 'CAD', 'AUD'));
// Shared per-spec data setup. Each spec's beforeEach RESETS then SEEDS via the app's /__test__
// endpoint — this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so a developer running its own spec sees the
// broken endpoint immediately instead of shipping it.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// Usage in a spec:
//   test.beforeEach(async () => { await resetAndSeed({ /* rows this spec needs */ }); });

